{"query": "-- Check for external resources that might have protein data
SELECT DISTINCT resource_type, COUNT(*) as count
FROM resource_sample
WHERE resource_id IN (
  SELECT resource_id FROM resource_definition 
  WHERE cancer_study_id IN (
    SELECT cancer_study_id FROM cancer_study WHERE cancer_study_identifier = 'msk_chord_2024'
  )
)
GROUP BY resource_type;"}

